const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const wizard=$('#wizard'),form=$('#willForm'),panels=$$('.panel'),steps=$$('#stepList li');let current=0;
const titles=['Tell us about yourself','Tell us about your family','Record your wishes','Review your answers','Your draft is ready'];
const clean=v=>String(v||'').replace(/[<>]/g,'').trim();
function openWizard(){wizard.hidden=false;wizard.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';render();setTimeout(()=>$('input,select,textarea',panels[current])?.focus(),50)}
function closeWizard(){wizard.hidden=true;wizard.setAttribute('aria-hidden','true');document.body.style.overflow='';document.querySelector('[data-start]')?.focus()}
$$('[data-start]').forEach(b=>b.addEventListener('click',openWizard));$('#closeWizard').addEventListener('click',closeWizard);
wizard.addEventListener('click',e=>{if(e.target===wizard)closeWizard()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!wizard.hidden)closeWizard()});
form.addEventListener('change',e=>{if(e.target.name==='married'){$('#spouseWrap').hidden=e.target.value!=='Yes';form.spouse.required=e.target.value==='Yes'}if(e.target.name==='children'){$('#childrenWrap').hidden=e.target.value!=='Yes';form.childNames.required=e.target.value==='Yes'}save()});form.addEventListener('input',save);
function save(){const data=Object.fromEntries(new FormData(form));localStorage.setItem('legacyPathDemo',JSON.stringify(data));$('#saveStatus').textContent='Saved just now'}
function restore(){try{const d=JSON.parse(localStorage.getItem('legacyPathDemo')||'{}');Object.entries(d).forEach(([k,v])=>{const fields=$$(`[name="${k}"]`);fields.forEach(f=>{if(f.type==='radio'||f.type==='checkbox')f.checked=f.value===v||v==='on';else f.value=v})});$('#spouseWrap').hidden=d.married!=='Yes';form.spouse.required=d.married==='Yes';$('#childrenWrap').hidden=d.children!=='Yes';form.childNames.required=d.children==='Yes'}catch{localStorage.removeItem('legacyPathDemo')}}
function validate(){const fields=$$('input,select,textarea',panels[current]).filter(x=>!x.closest('[hidden]'));for(const f of fields){if(!f.checkValidity()){f.reportValidity();$('#formError').textContent='Please complete the highlighted question before continuing.';return false}}$('#formError').textContent='';return true}
function render(){panels.forEach((p,i)=>p.classList.toggle('active',i===current));steps.forEach((s,i)=>{s.classList.toggle('current',i===current);s.classList.toggle('complete',i<current)});$('#stepLabel').textContent=`STEP ${current+1} OF 5`;$('#wizardTitle').textContent=titles[current];$('#progressBar').style.width=`${(current+1)*20}%`;$('#backButton').hidden=current===0||current===4;$('#nextButton').hidden=current>=3;if(current===3)buildReview()}
function buildReview(){const d=Object.fromEntries(new FormData(form));const sections=[['About you',[['Name',`${clean(d.firstName)} ${clean(d.lastName)}`],['Location',`${clean(d.county)} County, ${clean(d.state)}`]]],['Family',[['Married',clean(d.married)],['Spouse',clean(d.spouse)||'Not applicable'],['Children',clean(d.children)],['Names',clean(d.childNames)||'Not applicable'],['Guardian',clean(d.guardian)||'Not provided']]],['Your wishes',[['Executor',clean(d.executor)],['Beneficiary',clean(d.beneficiary)],['Share',clean(d.share)],['Specific gift',clean(d.gift)||'None']]]];$('#reviewCards').innerHTML=sections.map((s,i)=>`<article class="review-card"><h3>${s[0]}</h3>${s[1].map(x=>`<span>${x[0]}</span><strong>${x[1]}</strong>`).join('')}<button type="button" data-edit="${i}">Edit this section</button></article>`).join('');$$('[data-edit]').forEach(b=>b.onclick=()=>{current=+b.dataset.edit;render()})}
$('#nextButton').addEventListener('click',()=>{if(!validate())return;current++;render()});$('#backButton').addEventListener('click',()=>{current--;render()});
$('.agree input').addEventListener('change',e=>{if(e.target.checked){current=4;render()}});
$('#payButton').addEventListener('click',()=>{const b=$('#payButton');b.disabled=true;b.textContent='Confirming simulated payment…';setTimeout(()=>{b.hidden=true;$('#downloadArea').hidden=false},850)});
function pdfEscape(s){return clean(s).normalize('NFKD').replace(/[^\x20-\x7E]/g,'').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)')}
function makePdf(){const d=Object.fromEntries(new FormData(form));const lines=['SAMPLE LAST WILL AND TESTAMENT','FICTIONAL CONCEPT DOCUMENT - NOT LEGALLY VALID','',`I, ${clean(d.firstName)} ${clean(d.lastName)}, of ${clean(d.county)} County, ${clean(d.state)}, declare this sample document.`,`Executor: ${clean(d.executor)}`,`Primary beneficiary: ${clean(d.beneficiary)}`,`Distribution: ${clean(d.share)}`,`Marital status: ${clean(d.married)}`,d.spouse?`Spouse: ${clean(d.spouse)}`:'',d.childNames?`Children: ${clean(d.childNames).replace(/\n/g,', ')}`:'',d.guardian?`Guardian: ${clean(d.guardian)}`:'',d.gift?`Specific instruction: ${clean(d.gift)}`:'','',`Generated: ${new Date().toLocaleDateString()}`,'This file demonstrates conditional form-to-document generation only.','It is not legal advice and is not a valid will.'].filter(Boolean);let y=750;const content=lines.map((l,i)=>{const size=i===0?17:i===1?9:11;const cmd=`BT /F1 ${size} Tf 55 ${y} Td (${pdfEscape(l).slice(0,100)}) Tj ET`;y-=i<2?27:21;return cmd}).join('\n');const objects=['1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj','2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj','3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources<< /Font<< /F1 4 0 R >> >> /Contents 5 0 R >>endobj','4 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj',`5 0 obj<< /Length ${content.length} >>stream\n${content}\nendstream\nendobj`];let pdf='%PDF-1.4\n',offs=[0];objects.forEach(o=>{offs.push(pdf.length);pdf+=o+'\n'});const xref=pdf.length;pdf+=`xref\n0 6\n0000000000 65535 f \n${offs.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
$('#downloadPdf').addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(makePdf());a.download='LegacyPath-Sample-Will.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
const answers=[[/probate/i,'Probate is the court process used to confirm a will and manage someone’s estate after death. Rules vary by location, so a qualified professional should review your situation.'],[/trust/i,'A trust can hold and manage property for chosen people or purposes. This demo does not recommend a specific kind of trust.'],[/save|privacy|information|data/i,'This demo saves sample answers only in this browser using local storage. It does not send them to a server.'],[/payment|cost|price/i,'The $49 checkout is simulated. No card details are requested and no money is collected.'],[/legal|lawyer|valid/i,'This is a technology demonstration, not legal advice. A real service would use jurisdiction-specific, attorney-approved templates and clear review rules.'],[/will/i,'A will records wishes such as who manages an estate, who receives property, and who may care for minor children. Requirements vary by jurisdiction.']];
$('#chatLaunch').onclick=()=>{$('#chat').hidden=false;$('#chatInput').focus()};$('#closeChat').onclick=()=>{$('#chat').hidden=true;$('#chatLaunch').focus()};$('#chatForm').addEventListener('submit',e=>{e.preventDefault();const input=$('#chatInput'),q=clean(input.value);if(!q)return;$('#messages').insertAdjacentHTML('beforeend',`<div class="user">${q}</div>`);const hit=answers.find(a=>a[0].test(q));const reply=hit?hit[1]:'I can explain this demo’s will, trust, probate, privacy and payment features. For personal legal questions, please speak with a qualified attorney.';setTimeout(()=>{$('#messages').insertAdjacentHTML('beforeend',`<div class="bot">${reply}</div>`);$('#messages').scrollTop=$('#messages').scrollHeight},300);input.value=''});
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;try{c.registerTool({name:'start_will_demo',title:'Start will demo',description:'Open the visible guided will questionnaire.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){openWizard();return{status:'opened',step:current+1}}});c.registerTool({name:'get_demo_status',title:'Get demo status',description:'Read the current visible questionnaire step and completion status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{open:!wizard.hidden,step:current+1,title:titles[current],payment_simulated:!$('#downloadArea').hidden}}})}catch(e){console.warn('WebMCP unavailable',e)}}
restore();registerTools();
